async def act(page):
    # Plan:
    # 1. Use a relative goto directly to the order view for order_id 65 (common Magento URL pattern).
    # 2. Click "Edit" if present to open the editable order/address form.
    # 3. Fill the shipping (or billing) address fields with the requested values.
    # 4. Select the State/Province option for California if a select is present.
    # 5. Click "Save" to persist changes.
    # Notes: we attempt several common label names for Magento admin fields to be robust.

    # 1) Navigate to the order view page for order 65 using a relative path.
    await page.goto("/index.php/admin/sales_order/view/order_id/65/")
    await page.wait_for_load_state("networkidle")

    # 2) If there is an "Edit" button on the order view, click it to enable editing addresses.
    try:
        await page.get_by_role("button", name="Edit").click()
        await page.wait_for_load_state("networkidle")
    except Exception:
        # If no explicit Edit button is present, continue — the view might already be editable.
        pass

    # 3) Fill street address. Try multiple common label names.
    street_labels = ["Street Address", "Street", "Street 1", "Address"]
    for lbl in street_labels:
        try:
            await page.get_by_label(lbl).fill("789 Pine Lane")
            break
        except Exception:
            continue

    # 4) Fill city.
    try:
        await page.get_by_label("City").fill("San Francisco")
    except Exception:
        try:
            await page.get_by_label("Town/City").fill("San Francisco")
        except Exception:
            pass

    # 5) Select State/Province (Region). Try several common label names for selects.
    region_labels = ["State/Province", "Region", "State"]
    for rlbl in region_labels:
        try:
            # try selecting by visible label "California"
            await page.get_by_label(rlbl).select_option(label="California")
            break
        except Exception:
            try:
                # try selecting by value 'CA' as fallback
                await page.get_by_label(rlbl).select_option(value="CA")
                break
            except Exception:
                continue

    # 6) Fill postal/zip code. Try multiple label names.
    postal_labels = ["Zip/Postal Code", "ZIP/Postal Code", "ZIP Code", "Postal Code", "Postcode"]
    for plbl in postal_labels:
        try:
            await page.get_by_label(plbl).fill("94102")
            break
        except Exception:
            continue

    # 7) If there is a country select (rare if already set), ensure United States.
    try:
        await page.get_by_label("Country").select_option(label="United States")
    except Exception:
        try:
            await page.get_by_label("Country").select_option(value="US")
        except Exception:
            pass

    # 8) Click Save. This is expected to submit the form and possibly navigate; make it the last action.
    try:
        await page.get_by_role("button", name="Save").click()
    except Exception:
        # try a Save button within a form or container
        try:
            await page.get_by_role("form").get_by_role("button", name="Save").click()
        except Exception:
            # final fallback: press Enter on an input to submit
            try:
                # try pressing Enter on the first input we filled
                await page.get_by_label("City").press("Enter")
            except Exception:
                pass

    # Wait a moment for submission to complete
    await page.wait_for_load_state("networkidle")
